def hidden_rule_fn(state):
    def wrap_diff(a, b, mod=8):
        return min((b - a) % mod, (a - b) % mod) * ((b - a) % mod if (b - a) % mod <= 4 else (a - b) % mod)

    def grolp_dist(p1, p2):
        dx = min((p2['x'] - p1['x']) % 8, (p1['x'] - p2['x']) % 8)
        dy = min((p2['y'] - p1['y']) % 8, (p1['y'] - p2['y']) % 8)
        if p1['type'] == p2['type']:
            return dx * dy + 1
        else:
            return dx + 2 * dy

    def wrap_add(val, delta, mod=8):
        return (val + delta) % mod

    def one_step_toward(current, target, mod=8):
        """Move one step toward target in each coordinate."""
        dx = (target - current) % mod
        if dx > mod // 2:
            dx -= mod
        dy = (target - current) % mod
        if dy > mod // 2:
            dy -= mod
        # Move one step in the direction of the target
        if abs(dx) >= 1:
            move_x = 1 if dx > 0 else -1
        else:
            move_x = 0
        if abs(dy) >= 1:
            move_y = 1 if dy > 0 else -1
        else:
            move_y = 0
        return move_x, move_y

    next_state = []
    for i, particle in enumerate(state):
        # Find nearest neighbor by grolp_dist
        nearest_idx = -1
        nearest_dist = float('inf')
        for j, other in enumerate(state):
            if i != j:
                d = grolp_dist(particle, other)
                if d < nearest_dist:
                    nearest_dist = d
                    nearest_idx = j

        nearest = state[nearest_idx]

        # Determine movement based on type
        if particle['type'] == 'SPONT':
            # Move only in y toward nearest's y
            move_x, move_y = one_step_toward(particle['y'], nearest['y'])
            move_x = 0  # SPONT only moves in y
            new_x = particle['x']
            new_y = wrap_add(particle['y'], move_y)
        elif particle['type'] == 'VRIX':
            # Move in both x and y toward nearest
            move_x, move_y = one_step_toward(particle['x'], nearest['x']), one_step_toward(particle['y'], nearest['y'])
            new_x = wrap_add(particle['x'], move_x)
            new_y = wrap_add(particle['y'], move_y)
        elif particle['type'] == 'KRAUL':
            # Move in x toward nearest's x, and y toward nearest's y
            dx = (nearest['x'] - particle['x']) % 8
            if dx > 4:
                dx -= 8
            dy = (nearest['y'] - particle['y']) % 8
            if dy > 4:
                dy -= 8
            move_x = 1 if dx > 0 else (-1 if dx < 0 else 0)
            move_y = 1 if dy > 0 else (-1 if dy < 0 else 0)
            new_x = wrap_add(particle['x'], move_x)
            new_y = wrap_add(particle['y'], move_y)
        else:
            new_x = particle['x']
            new_y = particle['y']

        next_state.append({'type': particle['type'], 'x': new_x, 'y': new_y})

    return next_state
